package dev.interview.ledger;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.micrometer.core.instrument.MeterRegistry;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.slf4j.Logger;import org.slf4j.LoggerFactory;
import java.sql.Date;import java.time.*;import java.util.*;

@Service public class ReconciliationService {
  private static final Logger log=LoggerFactory.getLogger(ReconciliationService.class);
  private final JdbcTemplate db;private final MeterRegistry meters;private final ObjectMapper json;private final int shardCount,maxAttempts;private final long approvalThreshold,maxDailyAmount;
  ReconciliationService(JdbcTemplate db,MeterRegistry meters,ObjectMapper json,@Value("${app.reconciliation.shard-count:4}")int shards,@Value("${app.reconciliation.max-attempts:5}")int attempts,@Value("${app.adjustments.approval-threshold:10000}")long approval,@Value("${app.adjustments.max-daily-amount:1000000}")long daily){this.db=db;this.meters=meters;this.json=json;shardCount=shards;maxAttempts=attempts;approvalThreshold=approval;maxDailyAmount=daily;}
  public Map<String,Object> create(ApiModels.CreateReconciliation r){if(r.rangeEnd().isBefore(r.rangeStart()))throw new IllegalArgumentException("rangeEnd must be on or after rangeStart");String id="rec_"+UUID.randomUUID().toString().substring(0,12);db.update("insert into reconciliation_runs(id,source,range_start,range_end,status,attempt,created_at) values(?,?,?,?,?,?,?)",id,r.source(),r.rangeStart(),r.rangeEnd(),"CREATED",0,OffsetDateTime.now());log.info("event=reconciliation_created run_id={} source={}",id,r.source());return Map.of("reconciliationId",id,"status","CREATED","links",links(id));}
  @Transactional public Map<String,Object> run(String id,String key){var r=db.queryForMap("select * from reconciliation_runs where id=?",id);String old=(String)r.get("RUN_KEY");if(old!=null){if(!old.equals(key))throw new LedgerService.Conflict("RUN_ALREADY_STARTED_WITH_DIFFERENT_KEY");return details(id);}db.update("update reconciliation_runs set status='QUEUED',attempt=attempt+1,run_key=?,started_at=? where id=?",key,OffsetDateTime.now(),id);for(int s=0;s<shardCount;s++)db.update("insert into reconciliation_shards(run_id,shard_id,status,attempt,next_run_at) values(?,?,?,?,?)",id,s,"PENDING",0,OffsetDateTime.now());meters.counter("reconciliation.runs","status","queued").increment();log.info("event=reconciliation_queued run_id={} shard_count={} idempotency_key={}",id,shardCount,key);return details(id);}
  public List<Map<String,Object>> readyShards(){return db.queryForList("select * from reconciliation_shards where status in ('PENDING','ERROR_RETRYABLE') and next_run_at<=? and attempt<? order by next_run_at fetch first 8 rows only",OffsetDateTime.now(),maxAttempts);}
  @Transactional public void processShard(String runId,int shardId){int got=db.update("update reconciliation_shards set status='RUNNING',attempt=attempt+1,started_at=? where run_id=? and shard_id=? and status in ('PENDING','ERROR_RETRYABLE')",OffsetDateTime.now(),runId,shardId);if(got==0)return;long started=System.nanoTime();try{var run=db.queryForMap("select * from reconciliation_runs where id=?",runId);db.update("update reconciliation_runs set status='RUNNING' where id=? and status='QUEUED'",runId);LocalDate from=toDate(run.get("RANGE_START")),to=toDate(run.get("RANGE_END"));var internal=db.queryForList("select coalesce(stripe_object_id,ref_id) match_key,currency,sum(amount) total from ledger_entries where account_id in ('stripe_receivable','processor_cash') and created_at>=? and created_at<? group by coalesce(stripe_object_id,ref_id),currency",from.atStartOfDay().atOffset(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC));var external=db.queryForList("select match_key,currency,sum(amount) total from external_transactions where source=? and occurred_at>=? and occurred_at<? group by match_key,currency",run.get("SOURCE"),from.atStartOfDay().atOffset(ZoneOffset.UTC),to.plusDays(1).atStartOfDay().atOffset(ZoneOffset.UTC));Map<String,long[]> vals=new TreeMap<>();Map<String,String> currencies=new HashMap<>();for(var x:internal)add(vals,currencies,x,0);for(var x:external)add(vals,currencies,x,1);String cursor=null;for(var e:vals.entrySet())if(Math.floorMod(e.getKey().hashCode(),shardCount)==shardId){cursor=e.getKey();long in=e.getValue()[0],ex=e.getValue()[1],delta=in-ex;String state=delta==0?"MATCHED":"MISMATCHED",reason=delta==0?"INTERNAL_EQUALS_EXTERNAL":in==0?"EXTERNAL_ONLY":ex==0?"INTERNAL_ONLY":"AMOUNT_DIFFERENCE";int n=db.update("update reconciliation_items set internal_sum=?,external_sum=?,delta=?,currency=?,state=?,reason=?,last_error=null where run_id=? and match_key=?",in,ex,delta,currencies.get(e.getKey()),state,reason,runId,e.getKey());if(n==0)db.update("insert into reconciliation_items(run_id,match_key,internal_sum,external_sum,delta,currency,state,reason,last_error) values(?,?,?,?,?,?,?,?,?)",runId,e.getKey(),in,ex,delta,currencies.get(e.getKey()),state,reason,null);if(delta!=0)emit("RECONCILIATION_DISCREPANCY",runId,"{\"key\":\""+e.getKey()+"\",\"delta\":"+delta+",\"reason\":\""+reason+"\"}");}db.update("update reconciliation_shards set status='COMPLETED',cursor_key=?,completed_at=?,last_error=null,next_run_at=null where run_id=? and shard_id=?",cursor,OffsetDateTime.now(),runId,shardId);meters.timer("reconciliation.shard.duration","outcome","completed").record(Duration.ofNanos(System.nanoTime()-started));completeIfReady(runId);log.info("event=reconciliation_shard_completed run_id={} shard_id={} cursor={}",runId,shardId,cursor);}catch(Exception e){int attempt=db.queryForObject("select attempt from reconciliation_shards where run_id=? and shard_id=?",Integer.class,runId,shardId);String state=attempt>=maxAttempts?"ERROR_FATAL":"ERROR_RETRYABLE";long delay=Math.min(60,1L<<Math.min(attempt,6))+Math.floorMod(Objects.hash(runId,shardId,attempt),3);db.update("update reconciliation_shards set status=?,last_error=?,next_run_at=? where run_id=? and shard_id=?",state,truncate(e.getMessage()),OffsetDateTime.now().plusSeconds(delay),runId,shardId);db.update("update reconciliation_runs set status=? where id=?",state.equals("ERROR_FATAL")?"FAILED":"RUNNING",runId);meters.counter("reconciliation.shard.retries","outcome",state.toLowerCase()).increment();log.warn("event=reconciliation_shard_failed run_id={} shard_id={} attempt={} retry_seconds={} error={}",runId,shardId,attempt,delay,e.toString());}}
  private void add(Map<String,long[]>v,Map<String,String>c,Map<String,Object>x,int side){String k=x.get("MATCH_KEY")+"|"+x.get("CURRENCY");v.computeIfAbsent(k,z->new long[2])[side]=((Number)x.get("TOTAL")).longValue();c.put(k,(String)x.get("CURRENCY"));}
  private LocalDate toDate(Object o){return o instanceof LocalDate d?d:((Date)o).toLocalDate();}private String truncate(String s){return s==null?"unknown":s.substring(0,Math.min(230,s.length()));}private Map<String,String>links(String id){return Map.of("self","/api/reconciliations/"+id,"run","/api/reconciliations/"+id+"/run","items","/api/reconciliations/"+id+"#items");}
  private void emit(String type,String aggregate,String payload){db.update("insert into outbox_events values(?,?,?,?,?,?,?)","out_"+UUID.randomUUID().toString().substring(0,12),type,aggregate,payload,"PENDING",OffsetDateTime.now(),null);}private void completeIfReady(String id){Integer open=db.queryForObject("select count(*) from reconciliation_shards where run_id=? and status<>'COMPLETED'",Integer.class,id);if(open!=null&&open==0){db.update("update reconciliation_runs set status='COMPLETED',completed_at=? where id=?",OffsetDateTime.now(),id);meters.counter("reconciliation.runs","status","completed").increment();}}
  public Map<String,Object> details(String id){var run=db.queryForMap("select * from reconciliation_runs where id=?",id);var r=new LinkedHashMap<String,Object>(run);r.put("counts",db.queryForList("select state,count(*) count from reconciliation_items where run_id=? group by state",id));r.put("shards",db.queryForList("select * from reconciliation_shards where run_id=? order by shard_id",id));r.put("items",db.queryForList("select * from reconciliation_items where run_id=? order by state desc,match_key",id));r.put("links",links(id));return r;}
  public void importExternal(ApiModels.ImportExternal row){String hash=Hashing.sha256(row.toString());try{db.update("insert into external_transactions values(?,?,?,?,?,?,?,?)",row.externalId(),row.matchKey(),row.amount(),row.currency(),row.status(),OffsetDateTime.now(),hash,"STRIPE");meters.counter("external.rows","outcome","accepted").increment();}catch(DuplicateKeyException e){String old=db.queryForObject("select raw_hash from external_transactions where external_id=?",String.class,row.externalId());if(!hash.equals(old))throw new LedgerService.Conflict("EXTERNAL_ID_REUSED_WITH_DIFFERENT_PAYLOAD");meters.counter("external.rows","outcome","duplicate").increment();}}
  @Transactional public Map<String,Object> requestAdjustment(ApiModels.Adjustment req){db.queryForMap("select id from reconciliation_runs where id=?",req.reconciliationId());validateBalanced(req.entries());long total=req.entries().stream().mapToLong(e->Math.abs(e.amount())).sum()/2;Long today=db.queryForObject("select coalesce(sum(total_absolute),0) from adjustment_requests where cast(requested_at as date)=current_date and status in ('PENDING_APPROVAL','POSTED')",Long.class);if((today==null?0:today)+total>maxDailyAmount)throw new LedgerService.Conflict("DAILY_ADJUSTMENT_LIMIT_EXCEEDED");String id="adjreq_"+UUID.randomUUID().toString().substring(0,10),status=total>approvalThreshold?"PENDING_APPROVAL":"APPROVED";try{db.update("insert into adjustment_requests(id,reconciliation_id,reason,entries_json,total_absolute,status,requested_at) values(?,?,?,?,?,?,?)",id,req.reconciliationId(),req.reason(),json.writeValueAsString(req.entries()),total,status,OffsetDateTime.now());}catch(Exception e){throw new IllegalStateException(e);}if(status.equals("APPROVED"))return postAdjustment(id,"policy:auto");emit("ADJUSTMENT_APPROVAL_REQUIRED",req.reconciliationId(),"{\"adjustmentRequestId\":\""+id+"\",\"amount\":"+total+"}");return Map.of("adjustmentRequestId",id,"status",status,"totalAbsolute",total);}
  @Transactional public Map<String,Object> approveAdjustment(String id,String approver){return postAdjustment(id,approver);}private Map<String,Object>postAdjustment(String id,String approver){var req=db.queryForMap("select * from adjustment_requests where id=?",id);if("POSTED".equals(req.get("STATUS")))return Map.of("adjustmentRequestId",id,"status","POSTED","journalId",req.get("JOURNAL_ID"));List<Map<String,Object>>entries;try{entries=json.readValue((String)req.get("ENTRIES_JSON"),List.class);}catch(Exception e){throw new IllegalStateException(e);}String journal="adj_"+UUID.randomUUID().toString().substring(0,12);OffsetDateTime now=OffsetDateTime.now();for(var e:entries){String account=(String)e.get("accountId"),currency=(String)e.get("currency"),key=(String)e.get("matchKey");long amount=((Number)e.get("amount")).longValue();db.update("insert into ledger_entries values(?,?,?,?,?,?,?,?,?,?)","le_"+UUID.randomUUID().toString().substring(0,12),journal,account,currency,amount,"RECONCILIATION_ADJUSTMENT",key,null,req.get("REASON"),now);updateProjection(account,currency,amount,now);}db.update("update adjustment_requests set status='POSTED',approved_by=?,approved_at=?,journal_id=? where id=?",approver,now,journal,id);emit("ADJUSTMENT_POSTED",(String)req.get("RECONCILIATION_ID"),"{\"journalId\":\""+journal+"\"}");return Map.of("adjustmentRequestId",id,"status","POSTED","journalId",journal);}
  private void validateBalanced(List<ApiModels.AdjustmentEntry>e){Map<String,Long>s=new HashMap<>();for(var x:e)s.merge(x.currency(),x.amount(),Long::sum);if(s.values().stream().anyMatch(x->x!=0))throw new IllegalArgumentException("adjustment entries must balance to zero per currency");}private void updateProjection(String a,String c,long amount,OffsetDateTime now){int n=db.update("update balance_projection set balance=balance+?,version=version+1,updated_at=? where account_id=? and currency=?",amount,now,a,c);if(n==0)db.update("insert into balance_projection values(?,?,?,?,?)",a,c,amount,1,now);}
  public List<Map<String,Object>>all(){return db.queryForList("select * from reconciliation_runs order by created_at desc");}public List<Map<String,Object>>outbox(){return db.queryForList("select * from outbox_events order by created_at desc");}
}

